let productView=0,productSize='',productQty=1,productAdded=false,productZoom=false;
function selectedProduct(){return merchProducts.find(p=>p.id===new URLSearchParams(location.search).get('item'))||merchProducts[0]}
function productURL(id){return '/sso-uofa/product.html?item='+id}
function productColour(p){return p.id==='hoodie'?tr('Deep burgundy','عنابي داكن'):p.id==='tee'?tr('Ivory','عاجي'):tr('Natural canvas','قماش طبيعي')}
function productViews(p){return [P('Studio view','منظر الاستوديو'),P('On model · front','على العارض · الأمام'),P('On model · back','على العارض · الخلف'),P('Fabric & print','القماش والطباعة'),P('On campus','في الجامعة')]}
function productPhoto(p,index,extra=''){return index===0?`<img class="product-photo ${extra}" src="merch/${p.id}-studio.png" alt="${escapeOnboard(t(p.name)+' · '+t(productViews(p)[index]))}">`:`<div class="product-photo product-sheet ${extra}" role="img" aria-label="${escapeOnboard(t(p.name)+' · '+t(productViews(p)[index]))}" style="background-image:url('merch/${p.id}-gallery.png');background-position:${['0% 0%','100% 0%','0% 100%','100% 100%'][index-1]}"></div>`}
function sizeButtons(p,scope){return `<div class="product-size-heading"><b>${tr('Select size','اختر المقاس')}</b><small>${tr('Sizing confirmed at launch','تُؤكد المقاسات عند الإطلاق')}</small></div><div class="product-sizes" role="group" aria-label="${tr('Select size','اختر المقاس')}">${p.sizes.map(s=>`<button type="button" data-${scope}-size="${s}" aria-pressed="${(scope==='quick'?merchSize:productSize)===s}">${s==='One size'?tr('One size','مقاس واحد'):s}</button>`).join('')}</div>`}
function productSection(){const p=selectedProduct();const initialSize=new URLSearchParams(location.search).get('size');if(!productSize&&p.sizes.includes(initialSize))productSize=initialSize;return `<section class="section product-section" id="product"><div class="product-breadcrumb"><a href="/sso-uofa/merch.html">${tr('The collection','المجموعة')}</a><span>/</span><span>${t(p.name)}</span><a class="textlink" href="/sso-uofa/checkout.html">${tr('Your bag','حقيبتك')} <span data-cart-count></span> </a></div><div class="product-layout"><div class="product-gallery"><button id="product-stage" class="product-stage ${productZoom?'is-zoomed':''}" aria-label="${tr('Toggle image zoom','تكبير أو تصغير الصورة')}" aria-pressed="${productZoom}">${productPhoto(p,productView)}</button><div class="product-gallery-caption"><span id="product-view-caption">${t(productViews(p)[productView])}</span><span>${tr('Click image to zoom','اضغط الصورة للتكبير')} +</span></div><div class="product-thumbnails" role="group" aria-label="${tr('Product images','صور المنتج')}">${productViews(p).map((v,i)=>`<button data-product-view="${i}" aria-label="${t(v)}" aria-pressed="${productView===i}">${productPhoto(p,i)}<span>${t(v)}</span></button>`).join('')}</div><p class="product-image-note">${tr('AI-generated styling and material imagery. Physical samples may vary.','صور تنسيق وخامات مولدة بالذكاء الاصطناعي. قد تختلف العينات الفعلية.')}</p></div><div class="product-information"><div class="eyebrow">${tr('SSO UofA · Heritage collection','منظمة الطلاب السودانيين · مجموعة التراث')}</div><h2>${t(p.name)}</h2><p class="product-intro">${t(p.desc)}</p><div class="product-price-row"><span class="merch-price">${merchPrice(p.price)}</span><span class="tag">${tr('Coming soon','قريباً')}</span></div><small class="product-price-note">${tr('Estimated price · CAD','سعر تقديري · دولار كندي')}</small><p class="product-colour"><i style="background:${p.id==='hoodie'?'#612c32':'#e5d7be'}"></i>${productColour(p)}</p>${sizeButtons(p,'product')}<div class="product-purchase"><label for="product-qty">${tr('Quantity','الكمية')}</label><select id="product-qty">${Array.from({length:10},(_,i)=>`<option ${productQty===i+1?'selected':''}>${i+1}</option>`).join('')}</select><button class="button" id="product-add" ${!productSize?'disabled':''}>${tr('Add to bag','أضف للحقيبة')} </button></div><p id="product-added" role="status">${productAdded?tr('Added to your bag.','أُضيف إلى حقيبتك.'):tr('Choose a size to add this piece.','اختر مقاساً لإضافة القطعة.')}</p><a class="textlink" href="/sso-uofa/checkout.html">${tr('View bag & checkout','الحقيبة والدفع')} </a><div class="product-specs"><details open><summary>${tr('The design story','حكاية التصميم')}</summary><p>${p.id==='tote'?tr('A warm Sudanese welcome, with a flowing Nile-inspired illustration. A little reminder of home for your everyday campus routine.','ترحيب سوداني دافئ مع رسم مستوحى من النيل. تذكير بالبيت في يومك الجامعي.'):tr('Inspired by Meroë, Sudan’s enduring pyramid silhouettes and the connection between home and campus.','مستوحى من مروي وأهرامات السودان والصلة بين البيت والجامعة.')}</p></details><details><summary>${tr('Materials & construction','الخامات والتفاصيل')}</summary><p>${p.id==='hoodie'?tr('The design pairs a soft-looking knit exterior with ribbed cuffs and a hood. Fibre composition, fabric weight and print method will be confirmed after sampling.','يجمع التصميم مظهر نسيج ناعم مع أساور مضلعة وقبعة. تُحدد تركيبة الألياف ووزن القماش وطريقة الطباعة بعد اعتماد العينة.'):p.id==='tee'?tr('The design features a crew neckline, short sleeves and a fine-knit texture. Fibre composition, weight and print method will be confirmed after sampling.','يتميز التصميم بياقة دائرية وأكمام قصيرة ومظهر نسيج ناعم. تُحدد تركيبة الألياف والوزن والطباعة بعد اعتماد العينة.'):tr('The design features a natural canvas look, shoulder handles and a printed front. Fabric weight, dimensions and carrying capacity will be confirmed after sampling.','يتميز التصميم بمظهر قماش طبيعي ومقابض للكتف وطباعة أمامية. يُحدد وزن القماش والأبعاد وقدرة الحمل بعد اعتماد العينة.')}</p></details><details><summary>${tr('Fit & care','المقاس والعناية')}</summary><p>${tr('The images illustrate the intended look, not measured fit. A garment-specific size guide and care instructions will be published before orders open.','توضح الصور المظهر المقترح وليست قياساً للمقاس. يُنشر دليل المقاسات والعناية قبل فتح الطلبات.')}</p></details><details><summary>${tr('Pickup & availability','الاستلام والتوفر')}</summary><p>${tr('Campus pickup is planned. Final pricing, availability, pickup arrangements and return terms will be confirmed before launch. No payment or order is submitted by adding to your bag.','نخطط للاستلام في الجامعة. تُؤكد الأسعار والتوفر والاستلام وشروط الإرجاع قبل الإطلاق. الإضافة للحقيبة لا تُرسل طلباً أو دفعة.')}</p></details></div></div></div><div class="product-related"><div class="eyebrow">${tr('More from the collection','المزيد من المجموعة')}</div><div>${merchProducts.filter(x=>x.id!==p.id).map(x=>`<a href="${productURL(x.id)}"><img src="merch/${x.id}-studio.png" alt="${t(x.name)}" loading="lazy"><span>${t(x.name)}</span><b>${merchPrice(x.price)}</b></a>`).join('')}</div></div></section>`}
function bindProduct(){if(currentSitePage!=='product')return;const p=selectedProduct();document.title=t(p.name)+' · SSO UofA';if(p.sizes.length===1&&!productSize){productSize=p.sizes[0];document.querySelector('[data-product-size]').setAttribute('aria-pressed','true');document.querySelector('#product-add').disabled=false}document.querySelectorAll('[data-product-view]').forEach(b=>b.onclick=()=>{productView=Number(b.dataset.productView);productZoom=false;const stage=document.querySelector('#product-stage');stage.classList.remove('is-zoomed');stage.setAttribute('aria-pressed','false');stage.innerHTML=productPhoto(p,productView);document.querySelector('#product-view-caption').textContent=t(productViews(p)[productView]);document.querySelectorAll('[data-product-view]').forEach(x=>x.setAttribute('aria-pressed',x===b))});document.querySelector('#product-stage').onclick=e=>{productZoom=!productZoom;e.currentTarget.classList.toggle('is-zoomed',productZoom);e.currentTarget.setAttribute('aria-pressed',productZoom)};document.querySelectorAll('[data-product-size]').forEach(b=>b.onclick=()=>{productSize=b.dataset.productSize;document.querySelectorAll('[data-product-size]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelector('#product-add').disabled=false});document.querySelector('#product-qty').onchange=e=>productQty=Number(e.target.value);document.querySelector('#product-add').onclick=()=>{if(!p.sizes.includes(productSize))return;for(let i=0;i<productQty;i++)addCartItem(p.id,productSize);productAdded=true;document.querySelector('#product-added').textContent=tr('Added to your bag.','أُضيف إلى حقيبتك.')};}
